def backfill_property_modules(apps, schema_editor):
    """Give every existing property an explicit module assignment for each
    module its organization is subscribed to (plus core property management),
    so the new module selector reflects current availability without hiding
    any existing property."""
    Property = apps.get_model('properties', 'Property')
    PropertyModule = apps.get_model('properties', 'PropertyModule')
    Subscription = apps.get_model('subscriptions', 'Subscription')

    for property_record in Property.objects.all().iterator():
        modules = set(
            Subscription.objects.filter(organization_id=property_record.organization_id)
            .values_list('module', flat=True)
        )
        modules.add('property')
        for module in modules:
            PropertyModule.objects.get_or_create(
                organization_id=property_record.organization_id,
                property_id=property_record.pk,
                module=module,
                defaults={'is_enabled': True},
            )


def unbackfill_property_modules(apps, schema_editor):
    PropertyModule = apps.get_model('properties', 'PropertyModule')
    PropertyModule.objects.all().delete()


